/// Where a piece of information came from. The four layers are never mixed silently:
/// every answer fragment carries its layer so the user can see what is a retrieved fact,
/// what is remembered about them, and what merely came out of the model weights.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Layer {
    /// Generated by the neural network from its trained weights (unverified).
    ModelWeights,
    /// Retrieved from an external source (web) and verified, or stored verified knowledge.
    Retrieved,
    /// A fact the user asked us to remember about them or their preferences.
    UserMemory,
    /// Temporary conversation context for the current session.
    Context,
}

impl Layer {
    pub fn label(&self) -> &'static str {
        match self {
            Layer::ModelWeights => "model weights (unverified)",
            Layer::Retrieved => "retrieved knowledge",
            Layer::UserMemory => "user memory",
            Layer::Context => "conversation context",
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct SourceRef {
    pub url: String,
    pub title: String,
    pub domain: String,
    /// publication date as unix seconds, when known
    pub published: Option<i64>,
    pub fetched_at: i64,
}
